/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cash_session_transactions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `amount` decimal(38,2) NOT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `created_by` bigint NOT NULL,
  `expense_id` bigint DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  `payment_id` bigint DEFAULT NULL,
  `payment_method` varchar(255) DEFAULT NULL,
  `purchase_return_id` bigint DEFAULT NULL,
  `session_id` bigint NOT NULL,
  `supplier_payment_id` bigint DEFAULT NULL,
  `type` varchar(255) DEFAULT NULL,
  `withdrawal_id` bigint DEFAULT NULL,
  `invoice_no` varchar(255) DEFAULT NULL,
  `order_id` bigint DEFAULT NULL,
  `sales_return_id` bigint DEFAULT NULL,
  `counter_id` bigint DEFAULT NULL,
  `reference_no` varchar(255) DEFAULT NULL,
  `supplier_id` bigint DEFAULT NULL,
  `supply_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=148 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
