DROP TABLE IF EXISTS `supplies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `supplies` (
  `supply_id` bigint NOT NULL AUTO_INCREMENT,
  `balance_amount` decimal(14,2) NOT NULL,
  `branch_id` bigint NOT NULL,
  `discount` decimal(14,2) DEFAULT NULL,
  `grn_no` varchar(50) DEFAULT NULL,
  `invoice_no` varchar(50) DEFAULT NULL,
  `notes` varchar(255) DEFAULT NULL,
  `paid_amount` decimal(14,2) DEFAULT NULL,
  `payable_amount` decimal(14,2) NOT NULL,
  `payment_method` varchar(255) DEFAULT NULL,
  `payment_status` varchar(30) NOT NULL,
  `po_id` bigint DEFAULT NULL,
  `received_by` bigint NOT NULL,
  `rounding` decimal(14,2) DEFAULT NULL,
  `status` varchar(255) DEFAULT NULL,
  `subtotal` decimal(14,2) DEFAULT NULL,
  `supplier_id` bigint NOT NULL,
  `supply_date` datetime(6) DEFAULT NULL,
  `tax_amount` decimal(14,2) DEFAULT NULL,
  `total` decimal(14,2) DEFAULT NULL,
  PRIMARY KEY (`supply_id`),
  UNIQUE KEY `UKs09oc7to8j1yu6ta09tlgvws0` (`grn_no`)
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
